UPDATE "SeoMeta" SET "title"='About Shanze | Power Bank OEM/ODM Manufacturer', "description"='Learn about Shanze New Energy Technology Co., Ltd. and our OEM/ODM charging product development and manufacturing support.', "canonical"='https://shanzesz.com/about' WHERE "route"='/about';
UPDATE "SeoMeta" SET "title"='Power Banks & Wireless Chargers | OEM/ODM Products | Shanze', "description"='Explore Shanze magnetic power banks, wireless chargers and charging products available for OEM/ODM project enquiries.', "canonical"='https://shanzesz.com/products' WHERE "route"='/products';
UPDATE "SeoMeta" SET "title"='Power Bank Factory in China | Shanze Manufacturing', "description"='Explore Shanze charging product manufacturing equipment, production processes, workshop areas and quality-control support in China.', "canonical"='https://shanzesz.com/factory' WHERE "route"='/factory';
UPDATE "SeoMeta" SET "title"='Charging Product Quality Control | Shanze', "description"='Explore Shanze quality-control processes, testing capabilities, traceability and certificate management for charging product projects.', "canonical"='https://shanzesz.com/quality' WHERE "route"='/quality';
UPDATE "SeoMeta" SET "title"='Power Bank & Charging Industry Insights | Shanze', "description"='Read Shanze insights about power banks, wireless charging, OEM/ODM product development, manufacturing and sourcing.', "canonical"='https://shanzesz.com/news' WHERE "route"='/news';
UPDATE "SeoMeta" SET "title"='Contact Shanze | Get an OEM/ODM Power Bank Quote', "description"='Send your power bank or wireless charger OEM/ODM requirements to Shanze for product and quotation review.', "canonical"='https://shanzesz.com/contact' WHERE "route"='/contact';

UPDATE "Banner" SET "title"=replace(replace("title",'ENERCORE','Shanze'),'Enercore','Shanze'), "subtitle"=replace(replace(COALESCE("subtitle",''),'ENERCORE','Shanze'),'Enercore','Shanze'), "description"=replace(replace(COALESCE("description",''),'ENERCORE','Shanze'),'Enercore','Shanze');
UPDATE "Page" SET "title"=replace(replace("title",'ENERCORE','Shanze'),'Enercore','Shanze'), "excerpt"=replace(replace(COALESCE("excerpt",''),'ENERCORE','Shanze'),'Enercore','Shanze'), "content"=replace(replace("content",'ENERCORE','Shanze'),'Enercore','Shanze');
UPDATE "PageSection" SET "title"=replace(replace("title",'ENERCORE','Shanze'),'Enercore','Shanze'), "subtitle"=replace(replace(COALESCE("subtitle",''),'ENERCORE','Shanze'),'Enercore','Shanze'), "content"=replace(replace(COALESCE("content",''),'ENERCORE','Shanze'),'Enercore','Shanze'), "items"=replace(replace("items",'ENERCORE','Shanze'),'Enercore','Shanze');
UPDATE "Translation" SET "value"=replace(replace("value",'ENERCORE','Shanze'),'Enercore','Shanze');
UPDATE "Translation" SET "value"=(SELECT "specifications" FROM "Product" WHERE "Product"."id"="Translation"."entityId") WHERE "entityType"='Product' AND "field"='specifications' AND EXISTS(SELECT 1 FROM "Product" WHERE "Product"."id"="Translation"."entityId");
UPDATE "Product" SET "summary"=replace("summary",'combines dependable performance, certified safety and a refined design for retail and OEM programs.','is available for retail and OEM/ODM project review.'), "description"=replace("description",'Specifications, colors, packaging and compliance can be tailored to target markets.','Available options and compliance requirements are confirmed for each project before sampling.');
UPDATE "Translation" SET "value"=replace("value",'兼具可靠性能、认证安全与精致设计，适合零售和 OEM 项目。','支持零售与 OEM/ODM 项目评估。') WHERE "entityType"='Product' AND "field"='summary';
